#include <cstdint>
#include <iostream>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

[[nodiscard]] std::string decode(std::string_view text) {
  std::vector<std::int64_t> counts;
  std::vector<std::string> groups;
  std::string current;
  std::int64_t number = 0;
  for (const char c : text) {
    if (c >= '0' && c <= '9') {
      number = number * 10 + (c - '0');
    } else if (c == '[') {
      counts.push_back(number);
      groups.push_back(std::move(current));
      current.clear();
      number = 0;
    } else if (c == ']') {
      const std::int64_t repeat = counts.back();
      counts.pop_back();
      std::string previous = std::move(groups.back());
      groups.pop_back();
      for (std::int64_t i = 0; i < repeat; ++i) previous += current;
      current = std::move(previous);
    } else {
      current.push_back(c);
    }
  }
  return current;
}

int main() {
  std::cout << decode("3[a2[c]]") << '\n';
  std::cout << decode("2[abc]3[cd]ef") << '\n';
  std::cout << decode("abc") << '\n';
  std::cout << decode("3[a]2[bc]") << '\n';
  std::cout << "empty: \"" << decode("") << "\"\n";
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <queue>
#include <span>
#include <vector>

struct Point {
  std::int64_t x = 0;
  std::int64_t y = 0;
};

[[nodiscard]] std::int64_t sq_dist(const Point& p) { return p.x * p.x + p.y * p.y; }

// std::priority_queue calls this "less": comp(a, b) true means a leaves the heap after b, so the
// farthest point, the largest squared distance, sits on top and is the one dropped past k.
struct FartherFirst {
  bool operator()(const Point& a, const Point& b) const { return sq_dist(a) < sq_dist(b); }
};

[[nodiscard]] std::vector<Point> k_closest(std::span<const Point> points, std::int64_t k) {
  std::priority_queue<Point, std::vector<Point>, FartherFirst> farthest_on_top;
  for (const Point& p : points) {
    farthest_on_top.push(p);
    if (static_cast<std::int64_t>(farthest_on_top.size()) > k) farthest_on_top.pop();
  }
  std::vector<Point> closest;
  closest.reserve(farthest_on_top.size());
  while (!farthest_on_top.empty()) {
    closest.push_back(farthest_on_top.top());
    farthest_on_top.pop();
  }
  std::ranges::reverse(closest);  // the heap emptied farthest first; the answer wants nearest first
  return closest;
}

int main() {
  const std::vector<Point> a{{.x = 1, .y = 3}, {.x = -2, .y = 2}};
  for (const Point& p : k_closest(a, 1)) std::cout << std::format("({}, {}) ", p.x, p.y);
  std::cout << '\n';

  const std::vector<Point> b{{.x = 3, .y = 3}, {.x = 5, .y = -1}, {.x = -2, .y = 4}};
  for (const Point& p : k_closest(b, 2)) std::cout << std::format("({}, {}) ", p.x, p.y);
  std::cout << '\n';

  for (const Point& p : k_closest(b, 3)) std::cout << std::format("({}, {}) ", p.x, p.y);
  std::cout << '\n';
}

#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <utility>
#include <vector>

[[nodiscard]] std::optional<std::pair<std::ptrdiff_t, std::ptrdiff_t>> find_in_grid(
    const std::vector<std::vector<int>>& grid, int target) {
  const std::ptrdiff_t rows = std::ssize(grid);
  if (rows == 0) return std::nullopt;
  const std::ptrdiff_t cols = std::ssize(grid[0]);
  if (cols == 0) return std::nullopt;
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = rows * cols;  // half-open [lo, hi) over the grid flattened row by row
  while (lo < hi) {
    const std::ptrdiff_t mid = lo + (hi - lo) / 2;
    const std::ptrdiff_t r = mid / cols;
    const std::ptrdiff_t c = mid % cols;
    const int value = grid[static_cast<std::size_t>(r)][static_cast<std::size_t>(c)];
    if (value == target) return std::pair{r, c};
    if (value < target) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(const std::optional<std::pair<std::ptrdiff_t, std::ptrdiff_t>>& at) {
  return at ? std::format("({}, {})", at->first, at->second) : "no value";
}

int main() {
  const std::vector<std::vector<int>> grid{{1, 3, 5, 7}, {10, 11, 16, 20}, {23, 30, 34, 60}};
  std::cout << std::format("{} {} {} {}\n", show(find_in_grid(grid, 3)), show(find_in_grid(grid, 13)),
                           show(find_in_grid(grid, 60)), show(find_in_grid(grid, 1)));
  std::cout << std::format("empty grid: {}, empty row: {}\n", show(find_in_grid({}, 5)),
                           show(find_in_grid({{}}, 5)));
}
